class Solution {
    public int[][] kClosest(int[][] points,int k){
        Arrays.sort(points,Comparator.comparingLong(p->(long)p[0]*p[0]+(long)p[1]*p[1]));
        return Arrays.copyOf(points,k);
    }
}

code.kotlin:
class Solution {
    fun kClosest(points:Array<IntArray>,k:Int):Array<IntArray>{
        points.sortBy{
            it[0].toLong()*it[0]+it[1].toLong()*it[1]
        };
        return points.copyOfRange(0,k)
    }
}

code.cpp:
class Solution {
    public: vector<vector<int>> kClosest(vector<vector<int>>& points,int k){
        sort(points.begin(),points.end(),[](auto& a,auto& b){
            return (long long)a[0]*a[0]+(long long)a[1]*a[1]<(long long)b[0]*b[0]+(long long)b[1]*b[1];
        });
        return {
            points.begin(),points.begin()+k
        };
    }
};
